CREATE TABLE operator_user(id serial primary key, username varchar(80) unique not null, password_hash text not null);
CREATE TABLE throttle(name text primary key, attempts integer not null, since timestamptz not null default now());
CREATE TABLE account(id serial primary key, name varchar(100) unique not null, kind text not null check(kind in ('cash','bank','sales','expense','payable','receivable','equity','transit')), active boolean not null default true);
CREATE TABLE counter(id serial primary key, name varchar(80) unique not null, cash_id int unique not null references account, main boolean not null default false, active boolean not null default true);
CREATE UNIQUE INDEX one_main ON counter(main) WHERE main;
CREATE TABLE item(id serial primary key, name varchar(120) not null, category varchar(80) not null, unit varchar(20) not null, tracked boolean not null, active boolean not null default true);
CREATE UNIQUE INDEX item_name ON item(lower(trim(name)));
CREATE TABLE party(id serial primary key, name varchar(120) not null, kind text not null check(kind in ('customer','supplier')));
CREATE UNIQUE INDEX party_name ON party(lower(trim(name)),kind);
CREATE TABLE event(id bigserial primary key, day date not null, kind text not null, counter_id int references counter, party_id int references party, reference varchar(100) not null default '', reason text not null default '', origin bigint references event, actor int not null references operator_user, token uuid unique not null, digest text not null, created timestamptz not null default now());
CREATE INDEX event_day ON event(day,counter_id);
CREATE INDEX event_origin ON event(origin);
CREATE UNIQUE INDEX one_reversal ON event(origin) WHERE kind='reversal';
CREATE TABLE movement(id bigserial primary key, event_id bigint not null references event, src int not null references account, dst int not null references account, amount numeric(16,2) not null check(amount>0), check(src<>dst));
CREATE INDEX movement_src ON movement(src,event_id);
CREATE INDEX movement_dst ON movement(dst,event_id);
CREATE VIEW posting AS SELECT event_id,src account_id,-amount amount FROM movement UNION ALL SELECT event_id,dst,amount FROM movement;
CREATE TABLE line(id bigserial primary key,event_id bigint not null references event,item_id int not null references item, category varchar(80) not null, qty numeric(16,3), unit varchar(20) not null, amount numeric(16,2),stock_delta numeric(16,3) not null default 0,check(qty is null or qty>0),check(amount is null or amount>0));
CREATE INDEX line_item ON line(item_id,event_id);
CREATE TABLE observation(event_id bigint primary key references event, account_id int references account,item_id int references item, expected numeric(16,3) not null,actual numeric(16,3) not null check(actual>=0),handed numeric(16,2) not null default 0,received numeric(16,2) not null default 0,check(num_nonnulls(account_id,item_id)=1), check(handed>=received and received>=0 and handed<=actual));
CREATE TABLE receipt(event_id bigint primary key references event, mime text not null, content bytea not null);
CREATE TABLE config(key text primary key,value boolean not null);
CREATE VIEW live_event AS SELECT e.* FROM event e WHERE e.kind<>'reversal' AND NOT EXISTS(SELECT 1 FROM event r WHERE r.kind='reversal' AND r.origin=e.id);
CREATE VIEW closed_day AS SELECT DISTINCT ON(day) day,kind,id FROM event WHERE kind IN ('close','reopen') ORDER BY day,id DESC;
CREATE FUNCTION immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER protect_event BEFORE UPDATE OR DELETE ON event FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TRIGGER protect_move BEFORE UPDATE OR DELETE ON movement FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TRIGGER protect_line BEFORE UPDATE OR DELETE ON line FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TRIGGER protect_observation BEFORE UPDATE OR DELETE ON observation FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TRIGGER protect_receipt BEFORE UPDATE OR DELETE ON receipt FOR EACH ROW EXECUTE FUNCTION immutable();
INSERT INTO account(name,kind) VALUES ('Sales','sales'),('Expenses','expense'),('Supplier balances','payable'),('Customer balances','receivable'),('Opening and adjustments','equity'),('Cash in transit','transit'),('Main Counter cash','cash'),('Counter 2 cash','cash');
INSERT INTO counter(name,cash_id,main) SELECT 'Main Counter',id,true FROM account WHERE name='Main Counter cash';
INSERT INTO counter(name,cash_id) SELECT 'Counter 2',id FROM account WHERE name='Counter 2 cash';
INSERT INTO config VALUES ('physical_counts',true);
CREATE TABLE closing_snapshot(event_id bigint primary key references event,payload jsonb not null);
CREATE TRIGGER protect_snapshot BEFORE UPDATE OR DELETE ON closing_snapshot FOR EACH ROW EXECUTE FUNCTION immutable();
CREATE TABLE login_session(token uuid primary key, user_id int not null references operator_user, expires timestamptz not null);
CREATE INDEX login_expiry ON login_session(expires);
CREATE INDEX event_kind_day ON event(kind,day);
CREATE INDEX event_lower_reference ON event(lower(reference));
CREATE TABLE source_entry(event_id bigint primary key references event, payload jsonb not null);
CREATE TRIGGER protect_source BEFORE UPDATE OR DELETE ON source_entry FOR EACH ROW EXECUTE FUNCTION immutable();
